#include <iostream>

class Base {
    virtual bool equivalent(int code, int condition) const noexcept {
        // Base implementation
        return code == condition;
    }
};

class Derived : public Base {
    bool equivalent(int code, int condition) const noexcept override {
        // Derived implementation, e.g., with additional logic
        return code == condition + 1;  // Hypothetical override
    }
};

int main() {
    Base* ptr = new Derived();  // Pointer to Base, but object is Derived
    bool result = ptr->equivalent(5, 4);  // Virtual call: resolves to Derived::equivalent at runtime
    std::cout << "Result: " << result << std::endl;  // Outputs based on Derived's implementation
    delete ptr;
    return 0;
}
